def transform(grid):
    h, w = len(grid), len(grid[0])

    # Horizontal colored bands define the row-periodic pattern.
    bands = []
    for r in range(h):
        vals = set(grid[r])
        if len(vals) == 1 and next(iter(vals)) != 0:
            bands.append((r, grid[r][0]))
    if bands:
        k = len(bands)
        pattern = {}
        for r, color in bands:
            pattern[r % k] = color
        if len(pattern) == k:
            return [[pattern[r % k] for _ in range(w)] for r in range(h)]

    # Otherwise, infer a periodic pattern from colored straight lines.
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != 0]
    colors = set(v for _, _, v in cells)
    k = len(colors)
    coords = {
        "row": lambda r, c: r,
        "col": lambda r, c: c,
        "sum": lambda r, c: r + c,
        "diff": lambda r, c: c - r,
    }

    for f in coords.values():
        by_color = {}
        for r, c, v in cells:
            by_color.setdefault(v, set()).add(f(r, c))
        if all(len(s) == 1 for s in by_color.values()):
            pattern = {next(iter(s)) % k: v for v, s in by_color.items()}
            if len(pattern) == k:
                return [[pattern[f(r, c) % k] for c in range(w)]
                        for r in range(h)]

    return [row[:] for row in grid]
